{
	"name": "@navopw/opencode-notch",
	"version": "0.6.1",
	"description": "Dynamic Island-style macOS notch notifications for OpenCode",
	"keywords": [
		"opencode",
		"opencode-plugin",
		"macos",
		"notch",
		"dynamic-island",
		"notifications"
	],
	"type": "module",
	"packageManager": "bun@1.3.14",
	"os": [
		"darwin"
	],
	"cpu": [
		"arm64"
	],
	"author": "Stanislav Hetzel",
	"license": "MIT",
	"main": "./dist/index.js",
	"types": "./dist/index.d.ts",
	"exports": {
		".": {
			"types": "./dist/index.d.ts",
			"import": "./dist/index.js"
		},
		"./package.json": "./package.json"
	},
	"files": [
		"dist",
		"src",
		"swift"
	],
	"publishConfig": {
		"access": "public",
		"provenance": true
	},
	"repository": {
		"type": "git",
		"url": "git+https://github.com/navopw/opencode-notch.git"
	},
	"homepage": "https://github.com/navopw/opencode-notch#readme",
	"bugs": {
		"url": "https://github.com/navopw/opencode-notch/issues"
	},
	"scripts": {
		"typecheck": "tsc --noEmit",
		"check": "bun run typecheck",
		"build": "rm -rf dist && tsc -p tsconfig.build.json",
		"build:swift": "version=$(bun -p \"require('./package.json').version\") && rm -rf swift/notch.app swift/notch && mkdir -p swift/notch.app/Contents/MacOS && swiftc -O -swift-version 5 -parse-as-library -target arm64-apple-macos13.0 -o swift/notch.app/Contents/MacOS/notch swift/notch.swift && cp swift/Info.plist swift/notch.app/Contents/Info.plist && plutil -replace CFBundleVersion -string \"$version\" swift/notch.app/Contents/Info.plist && plutil -replace CFBundleShortVersionString -string \"$version\" swift/notch.app/Contents/Info.plist && codesign --force --deep --sign - swift/notch.app",
		"prepack": "bun run build && bun run build:swift"
	},
	"devDependencies": {
		"@opencode-ai/plugin": "^1.18.9",
		"@types/bun": "^1.3.14",
		"typescript": "^7.0.2"
	},
	"engines": {
		"bun": ">=1.3.0"
	}
}
